import stylesText from './meal-ingredient-picker.css?inline';
import bindingStylesText from '../barcode-binding.css?inline';
import { cssStyleSheet } from '../../../utils/css.js';
import { describeBarcodeBinding, describeBarcodeBound } from '../barcode-binding.js';

const DEFAULT_SEARCH_PLACEHOLDER = 'Search for food…';
import { HealthService } from '../../../services/health.service.js';
import { OpenFoodFactsService } from '../../../services/openfoodfacts.service.js';
import type { OFFProduct } from '../../../services/openfoodfacts.service.js';
import { inStoreItemCode } from '@motivation/shared';
import type { FoodItem } from '@motivation/shared';
import {
    HEALTH_EVENTS,
    createPickerCancelEvent,
    createScanBarcodeEvent,
    createAiEstimateEvent,
    type SelectLibraryItemEvent,
    type SelectOffItemEvent,
    type FoodLogBackEvent,
    type AddIngredientEvent,
} from '../health-events.js';
import { createComponentLogger } from '../../../utils/component-logger.js';
import '../food-log/food-search-results.component.js';
import '../food-log/food-log-detail.component.js';
import type { FoodSearchResults } from '../food-log/food-search-results.component.js';
import type { FoodLogDetail } from '../food-log/food-log-detail.component.js';

const styles = cssStyleSheet(stylesText);
const bindingStyles = cssStyleSheet(bindingStylesText);

const template = document.createElement('template');
template.innerHTML = `
    <div class="picker">
        <div class="picker-header">
            <button class="btn-secondary" id="back-btn" type="button">← Back to meal</button>
            <span class="picker-title" id="title">Add ingredient</span>
        </div>

        <div id="search-view">
            <div id="map-barcode-banner" class="map-banner" hidden>
                <span class="map-banner-code" id="map-barcode-code"></span>
                <p class="map-banner-scope" id="map-barcode-scope"></p>
                <label class="map-banner-consent">
                    <input type="checkbox" id="map-barcode-consent">
                    <span>Remember this code for the food I pick below</span>
                </label>
            </div>
            <div class="search-bar">
                <input id="search-input" type="text" placeholder="Search for food…">
            </div>
            <div class="alt-log-actions">
                <button class="alt-log-btn" id="scan-btn" type="button">Scan Barcode</button>
                <button class="alt-log-btn" id="ai-btn" type="button">AI Estimate</button>
            </div>
            <p class="pick-hint" id="pick-hint" hidden>Tap the food this barcode means</p>
            <div id="search-loading" class="loading-text" hidden>Searching…</div>
            <div id="search-error" class="error-text" hidden></div>
            <food-search-results id="results"></food-search-results>
        </div>

        <div id="detail-view" hidden>
            <div id="map-barcode-bound" class="map-bound" hidden>
                <span id="map-barcode-bound-text"></span>
                <button class="map-bound-change" id="map-barcode-change" type="button">Change</button>
            </div>
            <food-log-detail id="detail" mode="add-ingredient"></food-log-detail>
        </div>
    </div>
`;

/**
 * Self-contained ingredient picker for the meals screen. Composes
 * `<food-search-results>` and `<food-log-detail mode="add-ingredient">`
 * directly; owns its own view-swap. Emits ADD_INGREDIENT and PICKER_CANCEL
 * upward and **stops** the internal SELECT_FOOD_LOG_BACK events at this
 * boundary so the parent never has to drive the view.
 */
export class MealIngredientPicker extends HTMLElement {
    private readonly log = createComponentLogger('meal-ingredient-picker');
    private searchTimeout: ReturnType<typeof setTimeout> | null = null;
    private searchSeq = 0;
    private offAbort: AbortController | null = null;
    private currentQuery = '';
    private titleValue = 'Add ingredient';
    /** Story 342 — the code awaiting a food, and the one just bound to one. */
    private pendingBarcodeValue: string | null = null;
    private boundBarcodeValue: string | null = null;
    /** Story 344 — the opt-in. Nothing is bound unless the user ticked the box. */
    private bindConsentValue = false;

    constructor() {
        super();
        const shadow = this.attachShadow({ mode: 'open' });
        shadow.adoptedStyleSheets = [styles, bindingStyles];
        shadow.appendChild(template.content.cloneNode(true));
    }

    /** Optional title override for "edit ingredient" vs "add ingredient". */
    set title(value: string) {
        this.titleValue = value;
        const el = this.shadowRoot?.getElementById('title');
        if (el) el.textContent = value;
    }

    /** Open the picker with an existing food item pre-selected (edit ingredient flow). */
    showLibraryItem(item: FoodItem, initialAmount?: number): void {
        const detail = this.shadowRoot!.getElementById('detail') as FoodLogDetail;
        detail.showLibraryItem(item, initialAmount);
        this.showDetailView();
    }

    /** Show an OFF product directly in the detail view. */
    showProduct(product: OFFProduct): void {
        const detail = this.shadowRoot!.getElementById('detail') as FoodLogDetail;
        detail.showProduct(product);
        // Story 344: the item-code case arrives here with a code pending and no pick to
        // come — the detail's own box is where it is offered.
        detail.setPendingBind(this.pendingBarcodeValue, this.bindConsentValue);
        this.showDetailView();
    }

    /**
     * Resolve a barcode (library first, then OFF) and surface the result
     * in the detail view. Used by the scan-return flow on the meals screen.
     */
    async lookupBarcode(barcode: string): Promise<void> {
        // Story 342: a library FAILURE is not a library MISS — the same distinction 339
        // drew in the food log, which this path never got. A rejected lookup must not
        // reject the whole scan; Open Food Facts may still answer.
        let libraryItem: FoodItem | null = null;
        let library: 'miss' | 'failed' = 'miss';
        try {
            libraryItem = await HealthService.findFoodItemByBarcode(barcode);
        } catch (err) {
            library = 'failed';
            this.log.warn('barcode library lookup failed', { barcode, error: String(err) });
        }
        if (libraryItem) {
            this.showLibraryItem(libraryItem);
            return;
        }
        const { product, outcome, status } = await OpenFoodFactsService.lookupBarcode(barcode);
        if (product) {
            // Story 342: an item-code match answered with a sibling's code, so the code
            // actually scanned is still unknown. Keep it — adding the ingredient binds it.
            this.setPendingBarcode(outcome === 'found_by_item_code' ? barcode : null);
            this.showProduct(product);
            return;
        }
        // Story 339: the mirror of the food-log dead end, and it was equally silent.
        // No repeat counter here — this picker is not re-entered the way the scanner is.
        this.log.warn('barcode scan unresolved', {
            barcode,
            barcodeClass: inStoreItemCode(barcode) ? 'in_store' : 'gs1',
            itemCode: inStoreItemCode(barcode) ?? undefined,
            library,
            off: outcome,
            status,
        });
        const shadow = this.shadowRoot!;
        const errorEl = shadow.getElementById('search-error')!;
        errorEl.textContent = `Product not found for barcode ${barcode}.`;
        errorEl.hidden = false;
        // Story 342: 340 shipped the mapping table and named this component as a surface,
        // but only the logging half landed here — the pick that follows taught nothing.
        this.setPendingBarcode(barcode);
    }

    /** Story 342/344 — the pending offer, identical in shape to the food log's. */
    setPendingBarcode(barcode: string | null, consent = false): void {
        this.pendingBarcodeValue = barcode;
        this.bindConsentValue = Boolean(barcode) && consent;
        const shadow = this.shadowRoot;
        if (!shadow) return;
        const banner = shadow.getElementById('map-barcode-banner');
        const hint = shadow.getElementById('pick-hint');
        const box = shadow.getElementById('map-barcode-consent') as HTMLInputElement | null;
        const searchInput = shadow.getElementById('search-input') as HTMLInputElement | null;
        if (!banner || !hint) return;
        if (box) box.checked = this.bindConsentValue;
        if (barcode) {
            shadow.getElementById('map-barcode-code')!.textContent = barcode;
            shadow.getElementById('map-barcode-scope')!.textContent = describeBarcodeBinding(barcode).scope;
            banner.hidden = false;
            hint.hidden = !this.bindConsentValue;
            if (searchInput) {
                searchInput.placeholder = this.bindConsentValue
                    ? 'Search for the food this barcode means…'
                    : DEFAULT_SEARCH_PLACEHOLDER;
            }
        } else {
            banner.hidden = true;
            hint.hidden = true;
            if (searchInput) searchInput.placeholder = DEFAULT_SEARCH_PLACEHOLDER;
        }
    }

    get pendingBarcode(): string | null {
        return this.pendingBarcodeValue;
    }

    /** Story 344 — nothing is bound unless this is true. */
    get bindConsent(): boolean {
        return this.bindConsentValue;
    }

    private setBoundBarcode(barcode: string | null, foodName?: string): void {
        this.boundBarcodeValue = barcode;
        const shadow = this.shadowRoot;
        if (!shadow) return;
        const bar = shadow.getElementById('map-barcode-bound');
        if (!bar) return;
        if (barcode) {
            shadow.getElementById('map-barcode-bound-text')!.textContent =
                describeBarcodeBound(barcode, foodName ?? 'this food');
            bar.hidden = false;
        } else {
            bar.hidden = true;
        }
    }

    /**
     * Story 342 — bind the pending code to the food the user picked. Unlike the food-log
     * screen this needs no URL round trip: the picker handles its own pick events, so the
     * code never has to survive a rebuild.
     *
     * Never blocks: a failed mapping still leaves them their ingredient, and the only
     * cost is being asked again.
     */
    private async bindPendingBarcodeTo(item: FoodItem): Promise<void> {
        const barcode = this.pendingBarcodeValue;
        // Story 344: the pick is not consent — only the ticked box is.
        if (!barcode || !this.bindConsentValue) return;
        this.setPendingBarcode(null);
        try {
            await HealthService.mapFoodItemBarcode(item.id, barcode);
            this.log.debug('mapped unresolved barcode', { foodItemId: item.id, barcode });
            this.setBoundBarcode(barcode, item.display_name);
        } catch (err) {
            this.log.warn('mapping an unresolved barcode failed; the pick still stands', err);
        }
    }

    connectedCallback(): void {
        const shadow = this.shadowRoot!;
        shadow.getElementById('title')!.textContent = this.titleValue;

        const detail = shadow.getElementById('detail') as FoodLogDetail;
        detail.mode = 'add-ingredient';

        const search = shadow.getElementById('search-input') as HTMLInputElement;
        search.addEventListener('input', () => {
            if (this.searchTimeout) clearTimeout(this.searchTimeout);
            this.searchTimeout = setTimeout(() => void this.runSearch(search.value.trim()), 300);
        });
        search.addEventListener('keydown', (e: KeyboardEvent) => {
            if (e.key === 'Enter') {
                if (this.searchTimeout) clearTimeout(this.searchTimeout);
                void this.runSearch(search.value.trim());
            }
        });

        shadow.getElementById('scan-btn')!.addEventListener('click', () => {
            this.dispatchEvent(createScanBarcodeEvent());
        });
        shadow.getElementById('ai-btn')!.addEventListener('click', () => {
            this.dispatchEvent(createAiEstimateEvent());
        });

        // Story 344: ticking the box is the whole act of consent.
        shadow.getElementById('map-barcode-consent')!.addEventListener('change', (event) => {
            this.bindConsentValue = (event.target as HTMLInputElement).checked;
            if (this.pendingBarcodeValue) this.setPendingBarcode(this.pendingBarcodeValue, this.bindConsentValue);
        });

        // Story 344: the same opt-in reaches here from the detail view's own box, which
        // is where the item-code case is offered (no pick, so no banner).
        shadow.getElementById('detail')!.addEventListener('bind-consent-change', (event) => {
            this.bindConsentValue = (event as CustomEvent<{ consent: boolean }>).detail.consent;
        });

        // Story 342: re-ask for a code already bound. 340's newest-intent-wins means the
        // next pick replaces the mapping, so no unbind is needed.
        shadow.getElementById('map-barcode-change')!.addEventListener('click', () => {
            const code = this.boundBarcodeValue;
            if (!code) return;
            this.setBoundBarcode(null);
            this.setPendingBarcode(code);
            this.showSearchView();
        });

        shadow.getElementById('back-btn')!.addEventListener('click', () => {
            const detailView = shadow.getElementById('detail-view')!;
            if (detailView.hidden) {
                this.dispatchEvent(createPickerCancelEvent());
            } else {
                this.showSearchView();
            }
        });

        // Stop these at this boundary — the picker owns its view-swap.
        // Without stopPropagation they would bubble out of the meals screen
        // and be picked up by any listener up the tree. Listening on `this`
        // (the host) rather than the shadow root so the typed
        // HTMLElementEventMap overloads pick the right CustomEvent shapes.
        this.addEventListener(HEALTH_EVENTS.SELECT_LIBRARY_ITEM, (event: SelectLibraryItemEvent) => {
            event.stopPropagation();
            this.log.debug('select library item', { foodItemId: event.detail.id, name: event.detail.display_name });
            const item = event.detail;
            const detail = shadow.getElementById('detail') as FoodLogDetail;
            detail.showLibraryItem(item);
            detail.setPendingBind(null);
            this.showDetailView();
            // Story 342: the pick IS the answer to the pending question — bind it now,
            // then confirm on the detail view it just opened.
            void this.bindPendingBarcodeTo(item);
        });
        this.addEventListener(HEALTH_EVENTS.SELECT_OFF_ITEM, (event: SelectOffItemEvent) => {
            event.stopPropagation();
            this.log.debug('select OFF item', { barcode: event.detail.barcode, name: event.detail.product_name });
            const detail = shadow.getElementById('detail') as FoodLogDetail;
            detail.showProduct(event.detail);
            // Story 342: an OFF pick has no food row yet, so the binding waits for the
            // ingredient to be added. Say so before the save rather than after.
            detail.setPendingBind(this.pendingBarcodeValue, this.bindConsentValue);
            this.showDetailView();
        });
        // Story 342: the OFF path's binding point. `food-log-detail` resolves or creates
        // the food row before emitting this, so the id it carries is the one to bind.
        this.addEventListener(HEALTH_EVENTS.ADD_INGREDIENT, (event: AddIngredientEvent) => {
            void this.bindPendingBarcodeTo(event.detail.food_item);
        });
        this.addEventListener(HEALTH_EVENTS.FOOD_LOG_BACK, (event: FoodLogBackEvent) => {
            event.stopPropagation();
            this.log.debug('back to search');
            this.showSearchView();
        });

        search.focus();
    }

    disconnectedCallback(): void {
        if (this.searchTimeout) clearTimeout(this.searchTimeout);
        this.offAbort?.abort();
    }

    private showDetailView(): void {
        const shadow = this.shadowRoot!;
        shadow.getElementById('search-view')!.hidden = true;
        shadow.getElementById('detail-view')!.hidden = false;
    }

    private showSearchView(): void {
        const shadow = this.shadowRoot!;
        shadow.getElementById('search-view')!.hidden = false;
        shadow.getElementById('detail-view')!.hidden = true;
        // The confirmation belongs to the detail view we are leaving. `setBoundBarcode`
        // is a no-op when nothing is bound, so this is safe on every back-press.
        if (this.boundBarcodeValue) this.setBoundBarcode(null);
    }

    private async runSearch(query: string): Promise<void> {
        if (query.length < 2) return;
        this.currentQuery = query;
        const shadow = this.shadowRoot!;
        const results = shadow.getElementById('results') as FoodSearchResults;
        const loadingEl = shadow.getElementById('search-loading')!;
        const errorEl = shadow.getElementById('search-error')!;
        const seq = ++this.searchSeq;

        this.offAbort?.abort();
        this.offAbort = new AbortController();
        loadingEl.hidden = false;
        errorEl.hidden = true;
        results.clear();

        let libraryFailed = false;
        let offFailed = false;

        const finalize = (libraryCount: number, offCount: number) => {
            if (seq !== this.searchSeq) return;
            loadingEl.hidden = true;
            this.log.debug('search done', { query, libraryCount, offCount, libraryFailed, offFailed });
            if (libraryFailed && offFailed) {
                errorEl.textContent = 'Search failed. Please try again.';
                errorEl.hidden = false;
                return;
            }
            if (libraryCount === 0 && offCount === 0) {
                results.showEmpty('No products found');
            }
        };

        let libraryCount = 0;
        let offCount = 0;
        let libraryDone = false;
        let offDone = false;

        const tryFinalize = () => {
            if (libraryDone && offDone) finalize(libraryCount, offCount);
        };

        void HealthService.searchFoodItems(query)
            .then((items) => {
                if (seq !== this.searchSeq) return;
                libraryCount = items.length;
                libraryDone = true;
                if (items.length > 0) results.libraryItems = items;
                tryFinalize();
            })
            .catch((err) => {
                if (seq !== this.searchSeq) return;
                libraryFailed = true;
                libraryDone = true;
                this.log.warn('Library search failed', err);
                tryFinalize();
            });

        void OpenFoodFactsService.searchFood(query, { signal: this.offAbort.signal, page: 1 })
            .then((page) => {
                if (seq !== this.searchSeq) return;
                offCount = page.items.length;
                offDone = true;
                if (page.items.length > 0) {
                    results.offItems = page.items;
                    results.showLoadMore = page.page < page.pageCount;
                }
                tryFinalize();
            })
            .catch((err) => {
                if (seq !== this.searchSeq) return;
                if (err instanceof Error && err.name === 'AbortError') return;
                offFailed = true;
                offDone = true;
                this.log.warn('OFF search failed', err);
                tryFinalize();
            });
    }
}

if (!customElements.get('meal-ingredient-picker')) {
    customElements.define('meal-ingredient-picker', MealIngredientPicker);
}
